package com.game_manager.gm.workflow; import com.game_manager.gm.common.entity.BaseEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="workflow_instances") @Getter @Setter @NoArgsConstructor public class WorkflowInstance extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="definition_version_id",nullable=false)private WorkflowDefinitionVersion definitionVersion;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="requester_id",nullable=false,length=36)private UUID requesterId;@Column(nullable=false,length=160)private String title;@Column(nullable=false,precision=12,scale=2)private BigDecimal amount;@Column(nullable=false,length=1000)private String description;@Enumerated(EnumType.STRING)@Column(nullable=false,length=24)private WorkflowStatus status;@Column(name="current_step_key",length=60)private String currentStepKey;@Column(name="due_at")private Instant dueAt;@Column(nullable=false)private boolean escalated;@Column(name="completed_at")private Instant completedAt;}
